* START TIC monthly data;

* 1984-2011 data -----------------------------------------------------
------;
libname dlm '[redacted-path-0a49898a8ce5]';


* dataset ticdata_ftot pulled from https://www.treasury.gov/resource-
center/data-chart-center/tic/Pages/shlreports.aspx and converted to
SAS using StatTransfer;

data h1; set dlm.ticdata_ftot; run;

proc sql; create table h2 as select distinct
      country_code as t_country,
      country_name as cname,
      year(date) as year,
      month(date) as month,
      ftot_agcy_est_pos as lta_c,
      ftot_corp_est_pos as ltc_c,
      ftot_stk_est_pos as lte_c,
      ftot_treas_est_pos as ltt_c
      from h1;

* START World Bank data - 2000 - 2014;

* transpose to long;
proc sort data=dlm.wb_pop out=pop; by iso3; run;
proc transpose data=pop out=popt;
     by iso3;
run;

data pop; set popt;
     year = tranwrd(_NAME_,"v","")*1;
     rename col1=population;
     drop _name_;
run;

* START world bank data 2015;

* Manually changed variable names in excel before starting this
program... file wdi2015:
Country
iso3
gdp
population
xrate;

data a1;
      set dlm.wdi2015;
      year=2015;
      n_gdp=gdp*1;
      n_population=population*1;
      n_xrate=xrate*1;

* START tech development and exchange controls;

* dataset dlm.wb_techdata was converted from Excel to SAS using
StatTransfer;
* Excel file was pulled from World Bank website;

proc sql; create table biggy as select distinct
      country,
      iso3,
      2000 as year,
      y2000 as IT_NET_SECR_P6
      from dlm.wb_techdata
      where code="IT_NET_SECR_P6";
quit;

* loop through years;

%macro bigloop;%let k=2001;     %do %until (%eval(&k)=2017);

* START government effectiveness;

* Dataset wgi_sas converted from Excel using StatTransfer;

data junk; set dlm.wgi_sas;
      where code="GE.PER.RNK";
run;
data junk2; set junk;
      keep iso3 v:;
run;
proc sort data=junk2; by iso3; run;
proc transpose data=junk2 out=junk3; by iso3; run;
data junk4; set junk3;
      year=substr(_name_,2,4)*1;
      rename col1=ge_pctile;
      drop _name_;
run;
proc sql; create table junk5 as select distinct
      * from junk4
      where iso3 in (select distinct iso3 from temp)
;quit;
proc sql; create table wgi as select distinct
      *,
      ge_pctile gt 50 as goveff_high_full
      from junk5
      group by year;
quit;

* need one dummy for the whole sample -- make non-time-varying -- use
2012;
proc sql; create table wgi2 as select distinct
      iso3,
      goveff_high_full ge 0.5 as goveff_high_full
      from wgi where year=2012
      group by iso3;
quit;

data wgi_dummies; set wgi2; run;

* combine controls into one dataset;

proc sql; create table controls as select distinct
      a.*,
      b.localrate
      from wbcontrols a, dlm.indiv_rates b
      where a.iso3=b.iso3 and a.year=b.year;
quit;

proc sql; create table controls as select distinct
      a.*,
      b.it_cel_sets_p2
      from controls a, wbtech b
      where a.iso3=b.iso3 and a.year=b.year;
quit;

proc sql; create table controls as select distinct
      a.*,
      b.goveff_high_full
      from controls a, wgi_dummies b
      where a.iso3=b.iso3;
quit;

proc sql; create table controls as select distinct
      *,
      iso3 in ("BHS" "BMU" "CHE" "PAN") as tiea4,
      iso3 in ("BHS" "BMU" "CHE") as tiea3
      from controls;

/* comment this out so that it does not override existing data1.dta
proc export data=regdata outfile="[redacted-path-bf9f929fd4ac]"
replace;
run;
*/
data dlm.data1; set regdata; run;

* count obs to use as screens;
proc sql; create table descdata1 as select distinct
     country,
     iso3,
     haven,

     sum(missing(logequity_world)=0) as n_logequity_world,
     sum(missing(logequity_us)=0) as n_logequity_us,
     sum(missing(logequity_non_us)=0) as n_logequity_non_us,
     sum(missing(logdebt_world)=0) as n_logdebt_world,
     sum(missing(logdebt_us)=0) as n_logdebt_us,
     sum(missing(logdebt_non_us)=0) as n_logdebt_non_us,
     sum(missing(z_logequity_world)=0) as n_z_logequity_world,
     sum(missing(z_logequity_us)=0) as n_z_logequity_us,
     sum(missing(z_logequity_non_us)=0) as n_z_logequity_non_us,
     sum(missing(z_logdebt_world)=0) as n_z_logdebt_world,
     sum(missing(z_logdebt_us)=0) as n_z_logdebt_us,
     sum(missing(z_logdebt_non_us)=0) as n_z_logdebt_non_us
     from regdata
     group by country
     order by country;
quit;
proc sql; create table cpisfull as select distinct
      *
      from regdata
      where iso3 in (select distinct iso3 from descdata1 where
n_logequity_world=10 and n_logequity_us=10 and n_logdebt_us=10);
quit;
proc sql; create table zucmanfull as select distinct
      *
      from regdata
      where iso3 in (select distinct iso3 from descdata1 where
n_z_logequity_world=10 and n_z_logequity_us=10 and n_z_logdebt_us=10
and n_z_logequity_non_us=10);
quit;

