* GDP;

proc sort data=dlm.wb_gdp out=gdp; by country_code; where
missing(country_code)=0; run;
proc transpose data=gdp out=gdpt;
     var v:;
     by country_code;
run;

data gdp; set gdpt;
     year = substr(_NAME_,2,4)*1;
     gdp=col1*1;
     drop _name_ col1;
run;

* xrate;

proc sort data=dlm.wb_xrate out=xrate; by country_code; where
missing(country_code)=0; run;
proc transpose data=xrate out=xratet;
     var v:;
     by country_code;
run;

data xrate; set xratet;
     year = substr(_NAME_,2,4)*1;
     xrate=col1*1;
     drop _name_ col1;

run;

