* no XRATE for Euro countries, so add it;

proc sql; create table fx as select distinct country, iso3, xrate,
year from a1; quit;


proc sort data=dlm.euro out=eur; by country_code; where
country_code="EMU"; run;
proc transpose data=eur out=tempt;
     var v:;
     by country_code;
run;
data eur; set tempt;
     year = substr(_NAME_,2,4)*1;
     fx=round(col1*1,.001);
     rename country_code=iso3;
     drop _name_ col1;
run;

